import{_ as n,l as o,o as e,c as s,v as i,p as l,x as t,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"精简配置","description":"","frontmatter":{"title":"精简配置","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/thin-provisioning.md","filePath":"cs/thin-provisioning.md","lastUpdated":1789023840000}'),p={name:"cs/thin-provisioning.md"};function m(E,a,_,u,A,f){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="精简配置" tabindex="-1">精简配置 <a class="header-anchor" href="#精简配置" aria-label="Permalink to &quot;精简配置&quot;">​</a></h1><div class="epigraph"><p>精简池只在第一次写入时分配后端块；逻辑卷可以声称比池更大，直到真正写满才 ENOSPC。</p><footer>—— 据 Linux dm-thin 文档；存储行业对 thin provisioning 的实践整理</footer></div><p><a href="/cs/dm-crypt">上一课</a>不改变「逻辑块总对应物理块」。<a href="/cs/sparse-files">稀疏文件</a> 是 FS 层的洞。设备层也可以：<strong>thin</strong>。缺口是 dm-thin 的池、元数据、以及丢弃如何还块。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>虚拟机每人一块 100G 盘，实际平均用 10G。厚配置浪费。thin：逻辑设备 + 池；映射树（类似 extent）记录已写块。未映射读：返回零（或未定义，视实现）。写：分配池块，更新元数据（常有独立 metadata 设备）。缺口：池满时哪些卷失败；快照在 thin 上便宜（共享映射）；与 <a href="/cs/fs-quota">配额</a> 不同——这是块设备会计，不是 uid。</p><p><span class="marginnote">元数据耗尽与数据耗尽是两种满。thin 快照不是 btrfs subvol，但共享物理块的直觉相近。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一次写逻辑块 L：锁元数据，分配 P，写数据到 P，提交映射。读：查映射，无则零页。<code>discard</code> 删除映射，还池——<a href="/cs/discard-trim">TRIM</a> 后课。对照 LVM thick：创建时就切走 PV 空间。对照 FS fallocate：可在 thin 上仍触发分配，视是否传递。</p>',8)),(e(),l(c,null,{default:t(()=>[h(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20WR%5B%22%E5%86%99%E9%80%BB%E8%BE%91%E5%9D%97%22%5D%20--%3E%20MAP%5B%22thin%20%E6%98%A0%E5%B0%84%E6%A0%91%22%5D%0A%20%20MAP%20--%3E%7C%22%E6%9C%AA%E6%98%A0%E5%B0%84%22%7C%20ALLOC%5B%22%E6%B1%A0%E4%B8%AD%E5%88%86%E9%85%8D%22%5D%0A%20%20ALLOC%20--%3E%20PHY%5B%22%E7%89%A9%E7%90%86%E5%9D%97%22%5D%0A%20%20RD%5B%22%E8%AF%BB%E6%9C%AA%E6%98%A0%E5%B0%84%22%5D%20--%3E%20ZERO%5B%22%E9%9B%B6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>精简把超分配从管理承诺变成块层机制，使密度上升，也把「盘满」从创建时挪到运行时——监控变成必修。不要把它写成云计费产品课。与 RAID：thin 可叠在 md 上，池满与成员故障是不同失败。</p><p>崩溃：元数据必须日志或 COW，否则映射丢失——dm-thin 有自己的元数据事务。</p><p>实现上：元数据设备写满比数据池满更致命：映射无法更新，整池只读或失败。快照共享映射项，删除要延迟到引用为零，监控必须看 metadata 占用。 读法上只引用<a href="/cs/dm-crypt">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>精简配置</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CAS（内容寻址）重删的全部指纹。不保证每个 hypervisor 的 UNMAP 行为。下一课用快速盘给慢盘做缓存：bcache。</p><p>版本字段会变，课序钉的是机制对象「精简配置」，不是某一主线内核的结构体名。 后课默认：逻辑盘可超分配，写时占池。块层缓存数据盘，下一课 bcache。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>thin 按首次写分配；读洞得零。</li><li>池与元数据会分别耗尽。</li><li>bcache 是下一课。</li><li>出处：Linux dm-thin；LVM thin 文档；<em>OSTEP</em> 对分配的背景。</li></ul>',11))])}const b=n(p,[["render",m]]);export{B as __pageData,b as default};
